import{_ as s,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/faq.md","filePath":"fr/guide/faq.md","lastUpdated":1793163976000}'),a={name:"fr/guide/faq.md"};function n(p,e,o,l,u,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Q : Qu&#39;est-ce que NueZip ?</p><p>R : NueZip est un gestionnaire d&#39;archives professionnel pour macOS, prenant en charge la compression et l&#39;extraction de multiples formats d&#39;archives incluant RAR, ZIP, 7-Zip, TAR, GZIP et BZIP2.</p><p>Q : Quelles versions de macOS sont prises en charge ?</p><p>R : NueZip nécessite macOS 14 Sonoma ou ultérieur, et est optimisé pour les puces Apple Silicon (série M).</p><p>Q : Comment télécharger et installer NueZip ?</p><p>R : Téléchargez depuis le <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store</a> (recommandé) ou récupérez la dernière version depuis <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a>.</p><p>Q : NueZip est-il gratuit ?</p><p>R : NueZip propose un essai gratuit avec les fonctionnalités de base. Un achat unique débloque l&#39;ensemble complet des fonctionnalités, incluant les opérations par lot, la réparation d&#39;archives et le chiffrement avancé.</p><p>Q : Quels formats sont pris en charge ?</p><p>R : <strong>Lecture</strong> : RAR, ZIP, 7-Zip, TAR, GZIP, BZIP2, XZ, Zstandard<br><strong>Écriture (compression)</strong> : ZIP, 7-Zip, TAR, GZIP, BZIP2, XZ, Zstandard<br> Consultez l&#39;<a href="/fr/guide/introduction.html">Introduction</a> pour la matrice complète des formats.</p><p>Q : NueZip peut-il créer des archives RAR ?</p><p>R : Non. NueZip peut <strong>lire</strong> les archives RAR (y compris les archives multi-volumes et réparées), mais la compression RAR n&#39;est pas prise en charge en raison de restrictions de licence.</p><p>Q : NueZip est-il sûr pour les fichiers confidentiels ?</p><p>R : Oui. NueZip fonctionne entièrement hors ligne. Toutes les opérations s&#39;exécutent localement sur votre Mac. Le chiffrement AES-256 est disponible pour les archives ZIP protégées par mot de passe.</p><p>Q : NueZip téléverse-t-il mes fichiers vers le cloud ?</p><p>R : Non. NueZip est une application entièrement hors ligne. Vos fichiers ne sont jamais téléversés nulle part. Aucune connexion internet n&#39;est requise pour la compression ou l&#39;extraction.</p><p>Q : Comment mettre à jour l&#39;application ?</p><p>R : Mettez à jour via le Mac App Store (automatique) ou téléchargez la dernière version depuis GitHub Releases.</p><p>Q : Comment signaler des bugs ou demander des fonctionnalités ?</p><p>R : Ouvrez un problème sur le <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">dépôt GitHub</a>. Veuillez inclure votre version de macOS, votre version de NueZip et les étapes pour reproduire.</p><p>Q : Où sont stockés les journaux et les données ?</p><p>R : Pour les versions sandbox (App Store) :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Application Support/com.w3cub.nuezip/</span></span></code></pre></div><p>Les versions de développement peuvent écrire des journaux dans la console.</p><p>Si vous avez besoin de plus de réponses, veuillez ouvrir un problème dans le dépôt ou consulter la documentation complète.</p>',26)])])}const h=s(a,[["render",n]]);export{m as __pageData,h as default};
